#!/usr/bin/env python3
# -*- coding: utf-8 -*-

from __future__ import annotations

import base64
import re
import shutil
import sys
from datetime import datetime
from pathlib import Path

TARGET_NAME = "sync_project_control.py"
PART_CODE_B64 = ""


def main() -> int:

    script_directory = Path(__file__).resolve().parent
    target = script_directory / TARGET_NAME

    if not target.is_file():
        print(f"ERROR: File not found: {target}", file=sys.stderr)
        return 2

    original = target.read_text(encoding="utf-8")

    if "def run_part_six(args):" in original:
        print("NO CHANGES REQUIRED")
        print("Part VI is already installed.")
        return 0

    if "def run_part_five(" not in original:
        print("ERROR: Part V was not found.", file=sys.stderr)
        return 3

    call_pattern = re.compile(
        r"exit_code\s*=\s*run_part_five\(args\)"
    )

    if len(call_pattern.findall(original)) != 1:
        print(
            "ERROR: Expected exactly one run_part_five(args) call.",
            file=sys.stderr
        )
        return 4

    entry_pattern = re.compile(
        r'\nif __name__ == "__main__":\s*'
        r'\n\s*raise SystemExit\(\s*'
        r'\n\s*main\(\)\s*'
        r'\n\s*\)\s*',
        re.MULTILINE
    )

    entry_matches = list(entry_pattern.finditer(original))

    if len(entry_matches) != 1:
        print(
            "ERROR: Expected exactly one script entry point.",
            file=sys.stderr
        )
        return 5

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup = target.with_name(
        f"{target.name}.bak_part6_{timestamp}"
    )

    shutil.copy2(target, backup)

    updated = call_pattern.sub(
        "exit_code = run_part_six(args)",
        original,
        count=1
    )

    entry_match = entry_pattern.search(updated)

    if entry_match is None:
        print(
            "ERROR: Entry point could not be relocated.",
            file=sys.stderr
        )
        return 6

    without_entry = (
        updated[:entry_match.start()]
        + updated[entry_match.end():]
    )

    part_code = base64.b64decode(
        PART_CODE_B64.encode("ascii")
    ).decode("utf-8")

    final_entry = """

# =============================================================================
# SCRIPT ENTRY POINT
# =============================================================================

if __name__ == "__main__":
    raise SystemExit(
        main()
    )
"""

    assembled = (
        without_entry.rstrip()
        + "\n"
        + part_code.rstrip()
        + "\n"
        + final_entry
    )

    target.write_text(assembled, encoding="utf-8")

    verification = target.read_text(encoding="utf-8")

    required = (
        "class FileManifestSynchronizer:",
        "def validate_file_manifest_result(",
        "def print_manifest_change_plan(",
        "def run_part_six(args):",
        "exit_code = run_part_six(args)",
    )

    missing = [
        marker for marker in required
        if marker not in verification
    ]

    entry_count = verification.count(
        'if __name__ == "__main__":'
    )

    if missing or entry_count != 1:
        shutil.copy2(backup, target)
        print("PATCH ROLLED BACK", file=sys.stderr)

        if missing:
            print(
                "Missing markers: " + ", ".join(missing),
                file=sys.stderr
            )

        if entry_count != 1:
            print(
                f"Entry point count: {entry_count}",
                file=sys.stderr
            )

        return 7

    print("PATCH APPLIED")
    print(f"Updated : {target}")
    print(f"Backup  : {backup}")
    print()
    print("Part VI installed:")
    print("- File Manifest status synchronization")
    print("- CTRL-016 registration preview")
    print("- Canonical-state recalculation")
    print("- Three-document combined DRY RUN")
    print("- --apply remains blocked for safety")
    print()
    print("No YAML files were modified.")
    print()
    print("Next command:")
    print("python -B sync_project_control.py")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())